#include <string>
#include <vector>

class Solution {
public:
    bool isValid(std::string s) {
        if (s.length() % 2 != 0) {
            return false;
        }

        std::vector<char> st;
        st.reserve(s.length());

        for (char c : s) {
            if (c == '(' || c == '{' || c == '[') {
                st.push_back(c);
            } else {
                if (st.empty()) {
                    return false;
                }
                char top = st.back();
                if ((c == ')' && top == '(') ||
                    (c == '}' && top == '{') ||
                    (c == ']' && top == '[')) {
                    st.pop_back();
                } else {
                    return false;
                }
            }
        }

        return st.empty();
    }
};
